#include "fat.h"
#include "ata.h"
#include <stdint.h>
#include <stddef.h>
#define SECTOR_SIZE 512U
#define FAT_ATTR_DIR 0x10U
static uint8_t sector[SECTOR_SIZE];
static uint32_t volume_start,total_sectors,fat_start,root_start,data_start,sectors_per_fat,root_cluster;
static uint16_t root_entries;
static uint8_t sectors_per_cluster,fat_type;
static uint32_t cluster_count;
static uint32_t rd16(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8);}
static uint32_t rd32(const uint8_t*p){return rd16(p)|(rd16(p+2)<<16);}
static int readsec(uint32_t lba,void*b){return lba<0x10000000U&&ata_read_sector(lba,b);}
static int cluster_sector(uint32_t c,uint32_t n,uint32_t*out){uint64_t v=(uint64_t)data_start+(uint64_t)(c-2)*sectors_per_cluster+n;if(c<2||c>=cluster_count+2||n>=sectors_per_cluster||v>=0x10000000U)return 0;*out=(uint32_t)v;return 1;}
static int next_cluster(uint32_t c,uint32_t*out){uint32_t off,sec;if(fat_type==32)off=c*4U;else off=c*2U;sec=fat_start+off/SECTOR_SIZE;if(!readsec(sec,sector))return 0;*out=fat_type==32?(rd32(sector+(off%SECTOR_SIZE))&0x0FFFFFFFU):rd16(sector+(off%SECTOR_SIZE));if(*out>=0x0FFFFFF8U||*out>=0xFFF8U)return 2;if(*out<2||*out>=cluster_count+2)return 0;return 1;}
static int name_equal(const uint8_t*e,const char*n){char wanted[11];unsigned i,j=0;for(i=0;i<11;i++)wanted[i]=' ';while(*n&&j<11){if(*n=='/'){n++;continue;}if(*n=='.'){j=8;n++;continue;}char c=*n++;if(c>='a'&&c<='z')c=(char)(c-'a'+'A');wanted[j++]=c;}if(*n)return 0;for(i=0;i<11;i++)if(e[i]!=((uint8_t)wanted[i]))return 0;return 1;}
static int find_entry(uint32_t dir_cluster,int fixed_root,const char*name,uint8_t out[32],uint32_t*root_sector_out){uint32_t c=dir_cluster;uint32_t steps=0;if(fixed_root){uint32_t s;for(s=0;s<root_entries*32U/SECTOR_SIZE;s++){if(!readsec(root_start+s,sector))return 0;for(unsigned o=0;o<SECTOR_SIZE;o+=32){uint8_t*e=sector+o;if(e[0]==0)return 0;if(e[0]==0xE5||e[11]==0x0F)continue;if(name_equal(e,name)){for(unsigned k=0;k<32;k++)out[k]=e[k];if(root_sector_out)*root_sector_out=root_start+s;return 1;}}}return 0;}while(c>=2&&c<cluster_count+2&&steps++<cluster_count){for(unsigned n=0;n<sectors_per_cluster;n++){uint32_t lba;if(!cluster_sector(c,n,&lba)||!readsec(lba,sector))return 0;for(unsigned o=0;o<SECTOR_SIZE;o+=32){uint8_t*e=sector+o;if(e[0]==0)return 0;if(e[0]==0xE5||e[11]==0x0F)continue;if(name_equal(e,name)){for(unsigned k=0;k<32;k++)out[k]=e[k];if(root_sector_out)*root_sector_out=lba;return 1;}}}uint32_t next;int r=next_cluster(c,&next);if(r!=1)return 0;c=next;}return 0;}
int fat_init(void){uint32_t part=0;uint8_t mbr[512];if(!ata_init()||!readsec(0,mbr)||mbr[510]!=0x55||mbr[511]!=0xAA)return 0;/* Prefer a valid superfloppy BPB; otherwise use the first FAT partition. */if(rd16(mbr+11)==512&&mbr[13])part=0;else{unsigned i;for(i=0;i<4;i++){uint8_t*e=mbr+446+i*16;if(e[4]==0x0B||e[4]==0x0C||e[4]==0x06||e[4]==0x0E){part=rd32(e+8);break;}}if(!part)return 0;}volume_start=part;if(!readsec(volume_start,sector)||rd16(sector+11)!=512)return 0;sectors_per_cluster=sector[13];if(!sectors_per_cluster||(sectors_per_cluster&(sectors_per_cluster-1)))return 0;root_entries=(uint16_t)rd16(sector+17);total_sectors=rd16(sector+19);if(!total_sectors)total_sectors=rd32(sector+32);sectors_per_fat=rd16(sector+22);if(!sectors_per_fat)sectors_per_fat=rd32(sector+36);if(!total_sectors||!sectors_per_fat)return 0;fat_start=volume_start+rd16(sector+14);uint32_t fats=sector[16];uint32_t root_secs=((uint32_t)root_entries*32U+511U)/512U;data_start=fat_start+fats*sectors_per_fat+root_secs;root_start=fat_start+fats*sectors_per_fat;cluster_count=(total_sectors-(data_start-volume_start))/sectors_per_cluster;fat_type=cluster_count<4085?12:(cluster_count<65525?16:32);if(fat_type==12)return 0;root_cluster=fat_type==32?rd32(sector+44):0;return fat_type==32?(root_cluster>=2):(root_entries!=0);}
int fat_read_file(const char*path,void*buffer,size_t capacity,size_t*size){uint32_t dir=root_cluster;int fixed=(fat_type==16);uint8_t entry[32];if(!path||!buffer||!size)return 0;while(*path=='/')path++;for(;;){char part[13];unsigned n=0;while(*path&&*path!='/'){if(n>=12)return 0;part[n++]=*path++;}part[n]=0;while(*path=='/')path++;if(!n)return 0;if(!find_entry(dir,fixed,part,entry,0))return 0;uint32_t first=rd16(entry+26)|(rd16(entry+20)<<16);if(*path){if(!(entry[11]&FAT_ATTR_DIR)||first<2)return 0;dir=first;fixed=0;continue;}if(entry[11]&FAT_ATTR_DIR)return 0;uint32_t remaining=rd32(entry+28),c=first;size_t copied=0;uint32_t steps=0;if(remaining>capacity)return 0;while(remaining&&c>=2&&c<cluster_count+2&&steps++<cluster_count){for(unsigned s=0;s<sectors_per_cluster&&remaining;s++){uint32_t lba;if(!cluster_sector(c,s,&lba)||!readsec(lba,sector))return 0;size_t take=remaining<512?remaining:512;for(size_t j=0;j<take;j++)((uint8_t*)buffer)[copied+j]=sector[j];copied+=take;remaining-=(uint32_t)take;}if(remaining){uint32_t next;int r=next_cluster(c,&next);if(r!=1)return 0;c=next;}}if(remaining)return 0;*size=copied;return 1;}}
